And here's an example using SFML (C++) to create a simple window with a bouncing rectangle:

```cpp
#include <SFML/Graphics.hpp>

// Define some colors
sf::Color white = sf::Color::White;
sf::Color red = sf::Color::Red;

int main()
{
    // Create the game screen
    sf::RenderWindow window(sf::VideoMode(640, 480), "Bouncing Rectangle");

    // Set up rectangle properties
    sf::RectangleShape rect(sf::Vector2f(20.0f, 20.0f));
    rect.setFillColor(red);
    rect.setPosition(window.getSize().x / 2 - rect.getSize().x / 2,
                     window.getSize().y / 2 - rect.getSize().y / 2);

    while (window.isOpen())
    {
        // Handle events
        sf::Event event;
        while (window.pollEvent(event))
        {
            if (event.type == sf::Event::Closed)
                window.close();
        }

        // Move the rectangle
        float speed_x = 1.0f, speed_y = 2.0f;

        rect.move(speed_x, speed_y);

        // Bounce off edges
        if (rect.getPosition().x - rect.getSize().x / 2 < 0 ||
            rect.getPosition().x + rect.getSize().x / 2 > window.getSize().x)
            speed_x *= -1;
        if (rect.getPosition().y - rect.getSize().y / 2 < 0 ||
            rect.getPosition().y + rect.getSize().y / 2 > window.getSize().y)
            speed_y *= -1;

        // Draw everything
        window.clear(white);
        window.draw(rect);

        // Update the display
        window.display();
    }

    return EXIT_SUCCESS;
}
```

Remember to install Pygame or SFML libraries and set up your development environment according to their documentation.
